add_action( 'user_register', 'perfectpixel_default_address_new_users' );

function perfectpixel_default_address_new_users( $user_id ) {
	if ( ! is_admin() || ! current_user_can( 'create_users' ) ) {
		return;
	}
	$country = strtoupper( sanitize_text_field( '{{new_user_country}}' ) );
	$state   = strtoupper( sanitize_text_field( '{{new_user_state}}' ) );
	foreach ( array( 'billing', 'shipping' ) as $type ) {
		if ( $country && ! get_user_meta( $user_id, $type . '_country', true ) ) {
			update_user_meta( $user_id, $type . '_country', $country );
		}
		if ( $state && ! get_user_meta( $user_id, $type . '_state', true ) ) {
			update_user_meta( $user_id, $type . '_state', $state );
		}
	}
}
